BEGIN;
CREATE TABLE IF NOT EXISTS app_schema_migrations(version text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_users(id text PRIMARY KEY, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, project_name text, warehouse_id text, supplier_id text, department_id text);
CREATE TABLE IF NOT EXISTS app_roles(id text PRIMARY KEY, name text NOT NULL, data_scope text NOT NULL DEFAULT 'own' CHECK(data_scope IN ('company','project','warehouse','supplier','own','todo','department')));
CREATE TABLE IF NOT EXISTS app_user_roles(user_id text REFERENCES app_users(id),role_id text REFERENCES app_roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS app_permissions(id text PRIMARY KEY,module_id text NOT NULL,action text NOT NULL,UNIQUE(module_id,action));
CREATE TABLE IF NOT EXISTS app_role_permissions(role_id text REFERENCES app_roles(id),permission_id text REFERENCES app_permissions(id),PRIMARY KEY(role_id,permission_id));
ALTER TABLE app_records ADD COLUMN IF NOT EXISTS created_by text;
ALTER TABLE app_records ADD COLUMN IF NOT EXISTS updated_by text;
ALTER TABLE app_records ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
CREATE TABLE IF NOT EXISTS app_workflow_states(status text PRIMARY KEY,name text NOT NULL);
INSERT INTO app_workflow_states VALUES ('draft','草稿'),('submitted','已提交'),('reviewing','审核中'),('approved','已通过'),('rejected','已驳回'),('voided','已作废'),('archived','已归档') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS app_workflow_transitions(module_id text REFERENCES app_modules(module_id),from_state text REFERENCES app_workflow_states(status),action text,to_state text REFERENCES app_workflow_states(status),PRIMARY KEY(module_id,from_state,action));
INSERT INTO app_workflow_transitions SELECT module_id,s,a,t FROM app_modules CROSS JOIN (VALUES ('draft','saveDraft','draft'),('rejected','saveDraft','draft'),('draft','submit','submitted'),('rejected','submit','submitted'),('submitted','startReview','reviewing'),('submitted','approve','approved'),('reviewing','approve','approved'),('submitted','reject','rejected'),('reviewing','reject','rejected'),('draft','void','voided'),('rejected','void','voided'),('submitted','void','voided'),('approved','archive','archived'),('voided','archive','archived')) v(s,a,t) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS app_audit_logs(id bigserial PRIMARY KEY,operator text,role text,module_id text,record_id uuid,action text,before_status text,after_status text,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now(),request_no text,result text NOT NULL,error_message text);
CREATE INDEX IF NOT EXISTS app_audit_record_idx ON app_audit_logs(module_id,record_id,created_at);
CREATE TABLE IF NOT EXISTS app_operation_logs(id bigserial PRIMARY KEY,operator text,action text,request_no text,result text,error_message text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS app_todos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid REFERENCES app_records(id),assignee text REFERENCES app_users(id),status text NOT NULL DEFAULT 'pending',created_at timestamptz DEFAULT now(),completed_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS app_todos_pending_idx ON app_todos(record_id,assignee) WHERE status='pending';
CREATE TABLE IF NOT EXISTS app_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid REFERENCES app_records(id),name text NOT NULL,storage_key text NOT NULL,created_by text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS app_import_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),module_id text REFERENCES app_modules(module_id),created_by text,record_count integer,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS app_business_links(source_id uuid REFERENCES app_records(id),target_id uuid REFERENCES app_records(id),kind text,PRIMARY KEY(source_id,target_id,kind));
CREATE TABLE IF NOT EXISTS app_finance_settlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid UNIQUE REFERENCES app_records(id),payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz DEFAULT now());
INSERT INTO app_roles VALUES ('superAdmin','超级管理员','company'),('internal','内部管理用户','department'),('finance','财务人员','company'),('procurement','采购人员','project'),('equipmentManager','设备主管','company'),('warehouse','仓库人员','warehouse'),('supplier','供应商账号','supplier'),('driver','司机账号','own'),('operator','工程设备操作员账号','own'),('approver','审批人账号','todo'),('viewer','只读用户','own') ON CONFLICT DO NOTHING;
INSERT INTO app_users(id,name) VALUES ('admin','开发管理员'),('viewer','验证只读账号'),('approver','验证审批人') ON CONFLICT DO NOTHING;
INSERT INTO app_user_roles VALUES ('admin','superAdmin'),('viewer','viewer'),('approver','approver') ON CONFLICT DO NOTHING;
INSERT INTO app_permissions SELECT module_id||':'||a,module_id,a FROM app_modules CROSS JOIN unnest(ARRAY['view','create','edit','delete','submit','approve','reject','void','archive','import','export','audit','attachments']) a ON CONFLICT DO NOTHING;
INSERT INTO app_permissions VALUES ('system:manage','system','manage'),('system:audit','system','audit') ON CONFLICT DO NOTHING;
INSERT INTO app_role_permissions SELECT 'superAdmin',id FROM app_permissions ON CONFLICT DO NOTHING;
INSERT INTO app_role_permissions SELECT 'viewer',id FROM app_permissions WHERE action='view' ON CONFLICT DO NOTHING;
INSERT INTO app_role_permissions SELECT 'approver',id FROM app_permissions WHERE action IN ('view','approve','reject','attachments') ON CONFLICT DO NOTHING;
INSERT INTO app_role_permissions SELECT r.id,p.id FROM app_roles r CROSS JOIN app_permissions p WHERE (r.id='internal' AND p.action IN ('view','create','edit','submit','attachments')) OR (r.id='finance' AND p.module_id IN ('expenseReimburse','outsourcePayment','expenseMyApply','expensePaymentRecord') AND p.action IN ('view','create','edit','submit','approve','reject','export','attachments')) OR (r.id='procurement' AND p.module_id IN ('supplier','partsPurchase','purchaseInbound','contract') AND p.action IN ('view','create','edit','submit','import','export','attachments')) OR (r.id='equipmentManager' AND p.module_id IN ('engineeringEquipment','inbound','maintenance','workorder','dispatch','rental','returnPool') AND p.action IN ('view','create','edit','submit','approve','reject','archive','import','export','attachments')) OR (r.id='warehouse' AND p.module_id IN ('warehouse','parts','inbound','purchaseInbound') AND p.action IN ('view','create','edit','submit','attachments')) OR (r.id='supplier' AND p.module_id='supplier' AND p.action IN ('view','edit','submit','attachments')) OR (r.id IN ('driver','operator') AND p.module_id IN ('workorder','inspection') AND p.action IN ('view','create','edit','submit','attachments')) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS app_equipment_reservations(equipment_id uuid PRIMARY KEY REFERENCES app_records(id),source_id uuid REFERENCES app_records(id),previous_payload jsonb NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS app_stock_items(part_no text,warehouse_id text,quantity numeric NOT NULL CHECK(quantity>=0),updated_at timestamptz DEFAULT now(),PRIMARY KEY(part_no,warehouse_id));
CREATE TABLE IF NOT EXISTS app_stock_movements(source_id uuid PRIMARY KEY REFERENCES app_records(id),part_no text,warehouse_id text,quantity numeric NOT NULL,created_at timestamptz DEFAULT now());
INSERT INTO app_schema_migrations(version) VALUES ('business-v1') ON CONFLICT DO NOTHING;
COMMIT;
